function closeFileComments(d,file,outcome="file-deleted"){
  const now=Date.now();
  d.comments.filter(c=>c.status==="open"&&c.fileId===file.id).forEach(c=>{c.status=outcome;c.resolvedAt=now;c.resolvedBy=loginName()||"Initiator"});
}
function removeUploadedFile(d,fileId){
  if(!canModifyApproval(d)){toast(modificationBlockedMessage(d));return}
  const file=d.files.find(f=>f.id===fileId);
  if(!file||file.kind==="signing-sheet"){toast("The Approval Certificate is generated automatically");return}
  if(!confirm(`Delete “${file.name}” from this approval?`))return;
  const selectedId=d.files[activeFile]?.id;
  closeFileComments(d,file);
  d.files=d.files.filter(f=>f.id!==file.id);
  fileStoreDelete(file.id);
  if(file._previewUrl)URL.revokeObjectURL(file._previewUrl);
  d.revision++;
  d.status=d.sentAt?"revision":"draft";
  d.updatedAt=Date.now();
  evt("Uploaded file deleted",`${file.name} deleted · revision ${d.revision}`);
  syncSigningSheet(d);
  activeFile=selectedId&&selectedId!==file.id?d.files.findIndex(f=>f.id===selectedId):Math.max(0,Math.min(activeFile,d.files.length-1));
  if(activeFile<0)activeFile=0;
  save();
  renderEditor();
  toast("Uploaded file deleted");
}
