$("#changeSignerForm").onsubmit=async event=>{
  event.preventDefault();
  const d=current(),button=$("#confirmChangeSigner");
  if(!d||!replacementRecipientId){toast("Select a pending signer to replace");return}
  const snapshot=structuredClone(d);
  button.disabled=true;button.textContent="Changing signer…";
  try{
    const change=replaceSigner(d,replacementRecipientId,{name:$("#changeSignerName").value,email:$("#changeSignerEmail").value,reminderDays:+$("#changeSignerReminder").value,reason:$("#changeSignerReason").value});
    if(!(await cloudOwnerSave(d,{includeFiles:false,quiet:true}))){
      const index=state.documents.findIndex(document=>document.id===d.id);
      if(index>=0)state.documents[index]=snapshot;
      renderEditor();
      return
    }
    rememberContact(change.replacement.name,change.replacement.email);
    state.events.unshift({id:crypto.randomUUID(),at:Date.now(),text:"Signing authority changed",detail:change.detail,docId:d.id});
    save();renderEditor();$("#changeSignerDialog").close();event.target.reset();replacementRecipientId=null;
    if(d.sentAt){await deliverApprovalEmails(d,[change.replacement.id]);showSigningLinks(d,change.replacement.id);toast("Signer changed — the previous link is revoked and a new link was created")}else toast("Signer changed and the approval certificate was updated")
  }catch(error){toast(error.message||"The signer could not be changed")}
  finally{button.disabled=false;button.textContent="Change signer & create new link"}
};
