$("#addInitiatorComment").onclick=()=>{const d=current();if(!isDocumentInitiator(d)){toast('Only the recorded initiator login can add an initiator comment');return}const text=$("#initiatorCommentText").value.trim();if(!text){toast('Enter a document comment');return}d.comments.push({id:crypto.randomUUID(),author:loginName()||'Initiator',text,at:Date.now(),status:'open',kind:'note',audience:'all stakeholders'});evt('Initiator comment shared',text);$("#initiatorCommentText").value='';save();renderEditor();toast('Open comment shared with all stakeholders')};
$("#highlightBtn").onclick=()=>{highlightMode=!highlightMode;if(highlightMode){commentPlacementMode=false;renderEditor()}$("#highlightBtn").classList.toggle('active-control',highlightMode);toast(highlightMode?'Click the document to add highlights':'Highlight mode off')};
$("#documentCanvas").onclick=e=>{if(!highlightMode||e.target.closest('.placed-field'))return;const d=current(),file=d.files[activeFile],r=e.currentTarget.getBoundingClientRect();file.highlights??=[];file.highlights.push({id:crypto.randomUUID(),x:Math.max(1,Math.min(74,(e.clientX-r.left)/r.width*100)),y:Math.max(1,Math.min(96,(e.clientY-r.top)/r.height*100)),w:24,h:3});evt('Document highlighted',file.name);d.updatedAt=Date.now();save();renderEditor()};
let previewFallbackExpanded=false,previewPreviousZoom=1;
function previewIsExpanded(){return document.fullscreenElement===$('.canvas-wrap')||previewFallbackExpanded}
function updatePreviewExpandButton(){const expanded=previewIsExpanded(),button=$("#expandPreviewBtn");button.textContent=expanded?'× Exit full screen':'⛶ Expand';button.title=expanded?'Return to normal preview':'Open full-screen preview'}
function fitExpandedPreview(){const wrap=$('.canvas-wrap'),canvas=$("#documentCanvas");editorZoom=Math.max(.55,Math.min(1.35,(wrap.clientWidth-90)/760));canvas.style.zoom=editorZoom;$("#zoomReadout").textContent=`${Math.round(editorZoom*100)}%`}
async function togglePreviewExpanded(){const wrap=$('.canvas-wrap');if(previewIsExpanded()){if(document.fullscreenElement===wrap)await document.exitFullscreen();else{previewFallbackExpanded=false;wrap.classList.remove('preview-expanded');editorZoom=previewPreviousZoom;$("#documentCanvas").style.zoom=editorZoom;$("#zoomReadout").textContent=`${Math.round(editorZoom*100)}%`;updatePreviewExpandButton()}return}previewPreviousZoom=editorZoom;if(wrap.requestFullscreen){try{await wrap.requestFullscreen();requestAnimationFrame(fitExpandedPreview);return}catch{}}previewFallbackExpanded=true;wrap.classList.add('preview-expanded');fitExpandedPreview();updatePreviewExpandButton()}
$("#expandPreviewBtn").onclick=togglePreviewExpanded;$("#documentCanvas").ondblclick=e=>{e.preventDefault();togglePreviewExpanded()};$("#fileTabs").ondblclick=e=>{if(e.target.closest('button'))togglePreviewExpanded()};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){editorZoom=previewPreviousZoom;$("#documentCanvas").style.zoom=editorZoom;$("#zoomReadout").textContent=`${Math.round(editorZoom*100)}%`}updatePreviewExpandButton()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&previewFallbackExpanded){previewFallbackExpanded=false;$('.canvas-wrap').classList.remove('preview-expanded');editorZoom=previewPreviousZoom;$("#documentCanvas").style.zoom=editorZoom;$("#zoomReadout").textContent=`${Math.round(editorZoom*100)}%`;updatePreviewExpandButton()}});
$("#autoZoomBtn").onclick=()=>{const wrap=$('.canvas-wrap'),canvas=$("#documentCanvas");editorZoom=Math.min(1,(wrap.clientWidth-72)/760);editorZoom=Math.max(.45,editorZoom);canvas.style.zoom=editorZoom;$("#zoomReadout").textContent=`${Math.round(editorZoom*100)}%`;toast('Document fitted to available space')};
$('.canvas-wrap').addEventListener('wheel',e=>{if(!e.ctrlKey)return;e.preventDefault();editorZoom=Math.max(.4,Math.min(2,editorZoom+(e.deltaY<0?.1:-.1)));$("#documentCanvas").style.zoom=editorZoom;$("#zoomReadout").textContent=`${Math.round(editorZoom*100)}%`},{passive:false});
function downloadData(data,name){const a=document.createElement('a');a.href=data;a.download=name;a.click()}
function dataUrlBytes(data){const payload=data.split(',')[1],binary=atob(payload),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes}
function safePdfText(value){return String(value??'').replace(/[^\x20-\x7E]/g,' ').replace(/\s+/g,' ').trim()}
function fitPdfText(font,text,maxWidth,start=18,min=8){let size=start;while(size>min&&font.widthOfTextAtSize(text,size)>maxWidth)size--;return size}
