const CERTIFICATE_BORDER_THEMES={
  golden:["#6d3d15","#e66d12"],
  emerald:["#0b6c58","#2e7db5"],
  ocean:["#124f79","#14b8a6"],
  violet:["#60358a","#d946ef"],
  rose:["#8b294c","#f08a5d"],
  graphite:["#435467","#19a7a0"]
};
function hexToRgb(hex){const value=parseInt(hex.slice(1),16);return[(value>>16)&255,(value>>8)&255,value&255]}
async function themedCertificateBorderBytes(){
  const theme=document.documentElement.dataset.interfaceTheme||"golden";
  if(theme==="golden")return new Uint8Array(await (await fetch("assets/certificate-guilloche-border-6mm-gold.png")).arrayBuffer());
  const response=await fetch("assets/certificate-guilloche-border-6mm-gold.png"),bitmap=await createImageBitmap(await response.blob()),canvas=document.createElement("canvas");
  canvas.width=bitmap.width;canvas.height=bitmap.height;
  const context=canvas.getContext("2d",{willReadFrequently:true});
  context.drawImage(bitmap,0,0);
  const pixels=context.getImageData(0,0,canvas.width,canvas.height),[darkHex,lightHex]=CERTIFICATE_BORDER_THEMES[theme]||CERTIFICATE_BORDER_THEMES.golden,dark=hexToRgb(darkHex),light=hexToRgb(lightHex);
  for(let i=0;i<pixels.data.length;i+=4){
    if(!pixels.data[i+3])continue;
    const luminance=(pixels.data[i]*.2126+pixels.data[i+1]*.7152+pixels.data[i+2]*.0722)/255,t=Math.max(.08,Math.min(.92,luminance));
    pixels.data[i]=Math.round(dark[0]+(light[0]-dark[0])*t);
    pixels.data[i+1]=Math.round(dark[1]+(light[1]-dark[1])*t);
    pixels.data[i+2]=Math.round(dark[2]+(light[2]-dark[2])*t);
  }
  context.putImageData(pixels,0,0);
  return dataUrlBytes(canvas.toDataURL("image/png"));
}
const addDigitalApprovalPagesThemeBase=addDigitalApprovalPages;
