  canvas.width=1178;canvas.height=491;
  const context=canvas.getContext("2d"),[darkMask,accentMask]=await Promise.all(["assets/validoc-logo-dark-mask.png","assets/validoc-logo-accent-mask.png"].map(async url=>createImageBitmap(await (await fetch(url)).blob())));
